--
-- Table structure for table `albaran`
--

DROP TABLE IF EXISTS `albaran`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `albaran` (
  `id` smallint(3) unsigned zerofill NOT NULL AUTO_INCREMENT,
  `socio_id` mediumint(4) unsigned zerofill NOT NULL,
  `finca_id` smallint(4) unsigned zerofill NOT NULL,
  `anio` smallint(4) unsigned zerofill NOT NULL,
  `tecnico_id` mediumint(4) unsigned zerofill NOT NULL,
  `fecha_instrucciones` date NOT NULL,
  `fecha_ejecucion` date NOT NULL,
  `plazo_ejecucion_dias` smallint unsigned NOT NULL,
  `ejecucion_pendiente` bit(1) NOT NULL DEFAULT b'1',
  `riego_ce` decimal(2,1) unsigned NOT NULL,
  `riego_lm2` decimal(10,4) unsigned NOT NULL,
  `riego_tiempo_minutos` smallint unsigned NOT NULL,
  `equilibrio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci NOT NULL,
  `duracion_plan_abono` enum('1semana','15dias','1mes','indefinido') CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci NOT NULL DEFAULT 'indefinido',
  `tanque_dias_semana` set('lunes','martes','miercoles','jueves','viernes','sabado','domingo') CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci NOT NULL,
  `labores_culturales` set('eliminar-malas-hierbas','colocar-placas','despuntar','deshijar','deshojar','eliminar-plantas-viroticas','reponer-abejorros','entuturar','descolgar') CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci NOT NULL,
  `observaciones` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci,
  `firma` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci NOT NULL,
  PRIMARY KEY (`id`,`socio_id`,`finca_id`,`anio`),
  KEY `fk_albaran_socio_idx` (`socio_id`),
  KEY `fk_albaran_finca_idx` (`finca_id`),
  KEY `fk_albaran_tecnico_idx` (`tecnico_id`),
  CONSTRAINT `fk_albaran_finca` FOREIGN KEY (`finca_id`) REFERENCES `finca` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_albaran_socio` FOREIGN KEY (`socio_id`) REFERENCES `socio` (`usuario_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_albaran_tecnico` FOREIGN KEY (`tecnico_id`) REFERENCES `tecnico` (`usuario_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish2_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

