  `plazo_seguimiento` mediumint unsigned DEFAULT NULL,
  `dosis` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `plaga` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `producto_nombre_idx` (`nombre`)
) ENGINE=InnoDB AUTO_INCREMENT=14366 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish2_ci;
